function status(message,error=false){$('status').textContent=message;$('status').dataset.error=String(error);}
function field(id,fallback,min=-Infinity,max=Infinity){const v=Number($(id).value);if(!Number.isFinite(v)||v<min||v>max)throw Error(`${$(id).closest('label')?.childNodes[0]?.textContent.trim()||id}: ${min}~${max} 범위의 숫자를 입력하세요.`);return v;}
const labels={wa:'pA',wb:'pA',da:'ms',db:'ms',jitter:'ms','r-rest':'mV','r-threshold':'mV','r-tau':'ms','r-capacitance':'pF','r-adaptation':'pA','r-adaptTau':'ms'};
function updateLabels(){for(const [id,unit] of Object.entries(labels))$(id+'-value').textContent=`${num(Number($(id).value),['da','db','jitter','r-rest','r-threshold'].includes(id)?1:0)} ${unit}`;}
function persist(){
  try{
    const notes=Object.fromEntries(['question','hypothesis','variables','conclusion'].map(x=>[x,$('note-'+x).value.slice(0,8000)]));
    const controls=Object.fromEntries(['jitter','seed','duration','free-model','input-pattern','sound-weight','sound-inh','sound-delay','sound-jitter','sound-spacing','sound-seed','sound-angle','grid-min','grid-max','grid-wmin','grid-wmax'].map(x=>[x,$(x).value]));
    localStorage.setItem(key,JSON.stringify({notes,records,classCircuit,freeCircuit,realParams,fitLocked,frozenFit,lesson,inquiry,controls,cellId:getCell()?.id||previous.cellId,sweepId:getSweep()?.id||previous.sweepId,prediction:$('prediction').value.slice(0,8000)}));$('save-state').textContent='이 기기에 자동 저장됨';
  }catch{$('save-state').textContent='기기 저장을 사용할 수 없습니다. 결과 파일을 내려받으세요.';}
}
